/// <summary>
/// Batch service class for Recalculate attribute cache
/// </summary>
public class METRecalculateAttributeCacheService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// Processes the supplied <see cref="METRecalculateArrtibuteCacheContract"/> and recalculates the attribute cache
/// for each matching <see cref="InventTable"/> record returned by the contract query.
/// </summary>
public void process(METRecalculateAttributeCacheContract _contract)
{
    #OCCRetryCount
    InventTable                 inventTable;
    METGetAttributeValue        getAttributeValue;
    int                         recordsProcessed, erroredRecords;
    boolean                     parametersChanged = false;
    METUseCachedAttributesEnum  originalParameterValue;
    METUpdateParameters         updateParameters    = _contract.parmUpdateParameters();
    METDisplayInfoOnUpdate      displayInfoOnUpdate = _contract.parmDisplayInfoOnUpdate();
    EcoResProductParameters     ecoResProductParameters = EcoResProductParameters::find();
    Query                       query               = _contract.getQuery();
    QueryRun                    queryRun            = new QueryRun(query);

    try
    {
        if (updateParameters)
        {
            // Capture original value first (read outside update-transaction)
            ecoResProductParameters = EcoResProductParameters::find();
            originalParameterValue = ecoResProductParameters.METUseCachedAttributes;

            ttsbegin;
            ecoResProductParameters = EcoResProductParameters::find(true);
            ecoResProductParameters.METUseCachedAttributes = METUseCachedAttributesEnum::NoTrackValues;
            ecoResProductParameters.update();
            ttscommit;

            parametersChanged = true;
        }

        while (queryRun.next())
        {
            inventTable = queryRun.get(tableNum(InventTable));

            if (this.recalculateItem(inventTable, ecoResProductParameters, displayInfoOnUpdate))
            {
                ++recordsProcessed;
            }
            else
            {
                ++erroredRecords;
            }
        }

        if (updateParameters)
        {
            ttsbegin;
            ecoResProductParameters = EcoResProductParameters::find(true);
            ecoResProductParameters.METUseCachedAttributes = METUseCachedAttributesEnum::Yes;
            ecoResProductParameters.update();
            ttscommit;

            parametersChanged = false;
        }
    }
    finally
    {
        if (parametersChanged)
        {
            try
            {
                ttsbegin;
                ecoResProductParameters = EcoResProductParameters::find(true);
                ecoResProductParameters.METUseCachedAttributes = originalParameterValue;
                ecoResProductParameters.update();
                ttscommit;
            }
            catch (Exception::Error)
            {
                warning("@MET:UseCachedAttributesUpdateError");
            }
        }
    }

    Info(strFmt("@MET:AttributeCacheValueProcessed", recordsProcessed, erroredRecords));
}

/// <summary>
/// Recalculates attribute cache for a single item. Returns true when successful.
/// </summary>
private boolean recalculateItem(InventTable _inventTable, EcoResProductParameters _ecoResProductParameters, METDisplayInfoOnUpdate _displayInfoOnUpdate)
{
    #OCCRetryCount

    METGetAttributeValue    getAttributeValue;
    boolean                 succeeded;

    try
    {
        ttsbegin;
        getAttributeValue = METGetAttributeValue::newFromInventTable(_inventTable);
        getAttributeValue.setAttributeValues(_ecoResProductParameters, _displayInfoOnUpdate);
        ttscommit;

        succeeded = true;
    }
    catch (Exception::Deadlock)
    {
        // Retry logic for deadlocks
        if (xSession::currentRetryCount() < #RetryNum)
        {
            retry;
        }
        else
        {
            throw Exception::Deadlock;
        }
    }
    catch (Exception::UpdateConflict)
    {
        // Retry logic for update conflicts
        if (appl.ttsLevel() == 0 && xSession::currentRetryCount() < #RetryNum)
        {
            retry;
        }
        else
        {
            throw Exception::UpdateConflictNotRecovered;
        }
    }
    catch (Exception::Error)
    {
        // Log details and return false
        Global::exceptionTextFallThrough();
        warning(strFmt("@MET:CachedAttributeRecalculationError", _inventTable.ItemId));
        succeeded = false;
    }

    return succeeded;
}
